import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"TUI 桌面","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/tui-guide.md","filePath":"zh/manual/tui-guide.md"}'),o={name:"zh/manual/tui-guide.md"};function r(s,t,u,n,c,l){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="tui-桌面" tabindex="-1">TUI 桌面 <a class="header-anchor" href="#tui-桌面" aria-label="Permalink to &quot;TUI 桌面&quot;">​</a></h1><h2 id="启动桌面" tabindex="-1">启动桌面 <a class="header-anchor" href="#启动桌面" aria-label="Permalink to &quot;启动桌面&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; tui</span></span></code></pre></div><p>桌面会占用图形控制台（QEMU 需以 <code>-vga std</code> 运行）；串口保留 ush 提示符，可并行访问。</p><h2 id="屏幕布局" tabindex="-1">屏幕布局 <a class="header-anchor" href="#屏幕布局" aria-label="Permalink to &quot;屏幕布局&quot;">​</a></h2><ul><li>顶部<strong>面板</strong>：时钟、电源、系统摘要</li><li>中部<strong>桌面</strong>：应用启动器</li><li><strong>任务栏</strong>：运行中的 TUI 应用、启动器按钮</li></ul><p>键盘模型：方向键 + Enter 导航，ESC 后退，菜单键打开启动器。不强制使用鼠标——每个操作都能从键盘触达（这是无障碍门禁所断言的输入契约）。</p><h2 id="内置-tui-应用" tabindex="-1">内置 TUI 应用 <a class="header-anchor" href="#内置-tui-应用" aria-label="Permalink to &quot;内置 TUI 应用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>应用</th><th>功能</th></tr></thead><tbody><tr><td>tui-files</td><td>浏览 / 复制 / 移动 / 删除、启动 edit</td></tr><tr><td>tui-editor</td><td><code>edit</code> 命令所用的同一编辑器内核，带边框</td></tr><tr><td>tui-proc</td><td>进程表（<code>ps</code> 的数据）</td></tr><tr><td>tui-apps</td><td>应用启动器 / 注册表浏览器</td></tr><tr><td>tui-time</td><td>时钟（RTC / HPET / TSC）</td></tr><tr><td>tui-net</td><td>网络状态界面</td></tr><tr><td>tui-sysinfo / tui-hw / tui-drv / tui-sys</td><td>硬件 + 系统页面</td></tr></tbody></table><h2 id="tui-命令家族" tabindex="-1">TUI 命令家族 <a class="header-anchor" href="#tui-命令家族" aria-label="Permalink to &quot;TUI 命令家族&quot;">​</a></h2><p><code>tui</code>（桌面）、<code>tui-test</code>（自检）、<code>tui-hw</code>、<code>tui-net</code>、<code>tui-sysinfo [page]</code>、<code>tui-time</code>、<code>tui-drv [page]</code>、<code>tui-sys [page]</code>、<code>tui-ext</code>——全部是注册表程序，桌面运行期间也都可通过 shell 调用。</p><h2 id="tui-与大应用" tabindex="-1">TUI 与大应用 <a class="header-anchor" href="#tui-与大应用" aria-label="Permalink to &quot;TUI 与大应用&quot;">​</a></h2><p>TUI 呈现的是 8 个大应用所包装的同一批服务——sysinfo 页面读取的 L1SVC 操作与 <code>hwinfo</code> 相同。桌面是查看器；向导应用是操作员界面；经典命令是脚本界面——三扇门，一个系统。</p>',13)])])}const b=e(o,[["render",r]]);export{p as __pageData,b as default};
